from tinydb import TinyDB, where
from tinydb.storages import MemoryStorage
db = TinyDB(storage=MemoryStorage)
db.insert_multiple([{'a': 1}, {'a': None}, {'a': 5}, {}])

# Test all four comparison operators
try:
    result = [d['a'] for d in db.search(where('a') < 3)]
    print('<  works:', result)
except Exception as e:
    print('<  fails:', e)

try:
    result = [d['a'] for d in db.search(where('a') <= 3)]
    print('<= works:', result)
except Exception as e:
    print('<= fails:', e)

try:
    result = [d['a'] for d in db.search(where('a') > 3)]
    print('>  works:', result)
except Exception as e:
    print('>  fails:', e)

try:
    result = [d['a'] for d in db.search(where('a') >= 3)]
    print('>= works:', result)
except Exception as e:
    print('>= fails:', e)
